<?php
if ( ! defined( 'ABSPATH' ) ) exit;
class WPST_Widget_Badge_Grid extends WPST_Elementor_Widget_Base {
 public function get_name(){return 'wpsoft-badge-grid';} public function get_title(){return 'WPSoft Rozet / Avantaj Grid';} public function get_icon(){return 'eicon-apps';}
 protected function register_controls(){ $this->start_controls_section('content',array('label'=>'Rozetler')); $r=new \Elementor\Repeater(); $r->add_control('title',array('label'=>'Başlık','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'Güvenli')); $r->add_control('text',array('label'=>'Açıklama','type'=>\Elementor\Controls_Manager::TEXTAREA,'default'=>'Güncel ve güvenli altyapı.')); $this->add_control('items',array('label'=>'Rozetler','type'=>\Elementor\Controls_Manager::REPEATER,'fields'=>$r->get_controls(),'default'=>array(array('title'=>'Güvenli','text'=>'Güncel ve güvenli altyapı.'),array('title'=>'Hızlı','text'=>'Performans odaklı yapı.'),array('title'=>'Esnek','text'=>'Kolay geliştirilebilir.'),array('title'=>'Modern','text'=>'Güncel tasarım anlayışı.')),'title_field'=>'{{{ title }}}')); $this->wpst_signature_preset_control(); $this->add_control('layout',array('label'=>'Yerleşim','type'=>\Elementor\Controls_Manager::SELECT,'default'=>'grid','options'=>array('grid'=>'Grid','compact'=>'Compact','numbered'=>'Numbered','soft'=>'Soft Cards'),'prefix_class'=>'wpst-badge-layout-')); $this->add_responsive_control('columns',array('label'=>'Kolon','type'=>\Elementor\Controls_Manager::SELECT,'default'=>'4','tablet_default'=>'2','mobile_default'=>'1','options'=>array('1'=>'1','2'=>'2','3'=>'3','4'=>'4'),'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid'=>'grid-template-columns:repeat({{VALUE}},minmax(0,1fr))!important;'))); $this->add_responsive_control('gap',array('label'=>'Kart Aralığı','type'=>\Elementor\Controls_Manager::SLIDER,'range'=>array('px'=>array('min'=>0,'max'=>60)),'default'=>array('size'=>16),'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid'=>'gap:{{SIZE}}px;'))); $this->end_controls_section(); $this->start_controls_section('badge_style',array('label'=>'Kart Biçimi','tab'=>\Elementor\Controls_Manager::TAB_STYLE)); $this->add_control('accent',array('label'=>'Vurgu Rengi','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid article > span'=>'color:{{VALUE}};'))); $this->add_control('card_bg',array('label'=>'Kart Arka Plan','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid article'=>'background:{{VALUE}};'))); $this->add_control('title_color',array('label'=>'Başlık Rengi','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid h3'=>'color:{{VALUE}};'))); $this->add_control('text_color',array('label'=>'Metin Rengi','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid p'=>'color:{{VALUE}};'))); $this->add_group_control(\Elementor\Group_Control_Typography::get_type(),array('name'=>'title_typography','label'=>'Başlık Tipografisi','selector'=>'{{WRAPPER}} .wpst-ew-badge-grid h3')); $this->add_group_control(\Elementor\Group_Control_Typography::get_type(),array('name'=>'text_typography','label'=>'Metin Tipografisi','selector'=>'{{WRAPPER}} .wpst-ew-badge-grid p')); $this->add_responsive_control('card_padding',array('label'=>'Kart İç Boşluk','type'=>\Elementor\Controls_Manager::DIMENSIONS,'size_units'=>array('px'),'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid article'=>'padding:{{TOP}}px {{RIGHT}}px {{BOTTOM}}px {{LEFT}}px;'))); $this->add_responsive_control('card_radius',array('label'=>'Kart Köşe','type'=>\Elementor\Controls_Manager::SLIDER,'range'=>array('px'=>array('min'=>0,'max'=>60)),'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid article'=>'border-radius:{{SIZE}}px;'))); $this->add_control('border_color',array('label'=>'Kenarlık Rengi','type'=>\Elementor\Controls_Manager::COLOR,'selectors'=>array('{{WRAPPER}} .wpst-ew-badge-grid article'=>'border-color:{{VALUE}};'))); $this->add_control('hover_lift',array('label'=>'Hover Yükselme','type'=>\Elementor\Controls_Manager::SWITCHER,'return_value'=>'yes','default'=>'yes','prefix_class'=>'wpst-badge-hover-')); $this->end_controls_section(); 
        $this->standard_responsive_controls();
    }
 protected function render(){ $s=$this->get_settings_for_display(); echo '<div class="wpst-ew-badge-grid">'; $n=1; foreach((array)$s['items'] as $i){ echo '<article><span>'.str_pad((string)$n,2,'0',STR_PAD_LEFT).'</span><h3>'.esc_html($i['title']).'</h3><p>'.esc_html($i['text']).'</p></article>'; $n++; } echo '</div>'; }
}